export const NEXUS_LOGO = "data:image/png;base64,";

function fmtDate(iso) { if (!iso) return "—"; const [y,m,d] = iso.split("-"); return `${d}/${m}/${y}`; }
function fmtNum(n) { return Number(n||0).toLocaleString("pt-BR"); }
// Mesma lógica de index.html (linhasPagamento) — negócios com pagamento em 2+ parcelas viram
// uma linha por pagamento na Confirmação, sem sinal de "+".
function quantidadePrimeiraParcela(n) {
  const somaSacasExtras = (n.pagamentos_extra || []).filter(p => p.unidade === "sc").reduce((s, p) => s + Number(p.valor || 0), 0);
  return Math.max(0, Number(n.quantidade || 0) - somaSacasExtras);
}
function linhasPagamento(n) {
  const extras = n.pagamentos_extra || [];
  // Quando a 1ª parcela extra cai na mesma data do campo-base "Data de pagamento", é a mesma
  // parcela lançada duas vezes (comum quando o corretor lança todas as parcelas em "Pagamentos
  // adicionais" em vez de deixar a 1ª implícita no campo-base) — trata os extras como a lista
  // completa das parcelas, sem repetir a data base como uma linha fantasma à parte.
  if (extras.length && extras[0].data === n.data_pagamento) {
    return extras.map((p, i) => {
      const valor = p.unidade === "sc" ? `${fmtNum(p.valor)} sc` : fmtMoney(p.valor);
      return [`DATA DE PAGAMENTO (${i + 1}ª PARC)`, `${fmtDate(p.data)} — ${valor}`];
    });
  }
  const linhas = [[`DATA DE PAGAMENTO${extras.length ? " (1ª PARC)" : ""}`, (n.pagamento_dias_apos_entrega != null ? `${n.pagamento_dias_apos_entrega} DIAS APÓS A ENTREGA (previsto ${fmtDate(n.data_pagamento)})` : fmtDate(n.data_pagamento)) + (extras.length ? ` — ${fmtNum(quantidadePrimeiraParcela(n))} sc` : "")]];
  extras.forEach((p, i) => {
    const valor = p.unidade === "sc" ? `${fmtNum(p.valor)} sc` : fmtMoney(p.valor);
    linhas.push([`DATA DE PAGAMENTO (${i + 2}ª PARC)`, `${fmtDate(p.data)} — ${valor}`]);
  });
  return linhas;
}
function fmtMoney(n) { return "R$ " + Number(n||0).toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
function contaBancariaDoNegocio(n, vendedor) {
  if (n.conta_bancaria === "Terciária" && vendedor.dados_bancarios_terciaria) return vendedor.dados_bancarios_terciaria;
  if (n.conta_bancaria === "Secundária" && vendedor.dados_bancarios_secundaria) return vendedor.dados_bancarios_secundaria;
  return vendedor.dados_bancarios || "—";
}
// Diz se um documento é CPF (até 11 dígitos) ou CNPJ (mais de 11 dígitos) — alguns produtores
// rurais são cadastrados como pessoa jurídica (CNPJ) em vez de CPF, então o rótulo na
// Confirmação de Negócio precisa se ajustar sozinho em vez de dizer sempre "CPF".
export function tipoCpfCnpj(valor) {
  const digitos = String(valor || "").replace(/\D/g, "");
  if (!digitos) return "CPF";
  return digitos.length <= 11 ? "CPF" : "CNPJ";
}

// Fundersul e Fundems só se aplicam quando o comprador é Trading (ou sem categoria definida).
function aplicaFundersulFundems(comprador) {
  return !comprador || (comprador.categoria_comprador !== "Cooperativa" && comprador.categoria_comprador !== "Cerealista");
}
// Mesma conta de preço líquido usada no painel (index.html) e nas outras functions de WhatsApp/e-mail.
function precoLiquidoNegocio(n, comprador, config) {
  const sacas = Number(n.quantidade || 0);
  const total = Number(n.preco || 0) * sacas;
  const senar = total * 0.002;
  const comFundersulFundems = aplicaFundersulFundems(comprador);
  const fundersulTotal = comFundersulFundems ? Number(config.fundersul_saca || 0) * sacas : 0;
  const fundemsTotal = comFundersulFundems ? Number(config.fundems_saca || 0) * sacas : 0;
  const funruralForma = n.funrural_forma || "Comercialização";
  const funrural = funruralForma === "Comercialização" ? total * Number(config.funrural_pct || 0) / 100 : 0;
  const comissaoDoVendedor = n.comissao_pagador === "Comprador" ? 0 : Number(n.comissao || 0);
  const liquidoEstimado = total - comissaoDoVendedor - senar - fundersulTotal - fundemsTotal - funrural;
  const informado = n.preco_liquido != null && n.preco_liquido !== "";
  const precoLiquido = informado ? Number(n.preco_liquido) : (sacas ? liquidoEstimado / sacas : 0);
  const liquidoTotal = informado ? precoLiquido * sacas : liquidoEstimado;
  return { precoLiquido, liquidoTotal, informado };
}

function escapeHtml(s) { return String(s || "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;"); }
const EXTENSO_UNIDADES = ["", "um", "dois", "três", "quatro", "cinco", "seis", "sete", "oito", "nove"];
const EXTENSO_DEZ_A_DEZENOVE = ["dez", "onze", "doze", "treze", "catorze", "quinze", "dezesseis", "dezessete", "dezoito", "dezenove"];
const EXTENSO_DEZENAS = ["", "dez", "vinte", "trinta", "quarenta", "cinquenta", "sessenta", "setenta", "oitenta", "noventa"];
const EXTENSO_CENTENAS = ["", "cento", "duzentos", "trezentos", "quatrocentos", "quinhentos", "seiscentos", "setecentos", "oitocentos", "novecentos"];
function extensoGrupo(n) {
  if (n === 0) return "";
  if (n === 100) return "cem";
  const c = Math.floor(n / 100), r = n % 100;
  const partes = [];
  if (c) partes.push(EXTENSO_CENTENAS[c]);
  if (r) {
    if (r < 10) partes.push(EXTENSO_UNIDADES[r]);
    else if (r < 20) partes.push(EXTENSO_DEZ_A_DEZENOVE[r - 10]);
    else { const d = Math.floor(r / 10), u = r % 10; partes.push(EXTENSO_DEZENAS[d] + (u ? " e " + EXTENSO_UNIDADES[u] : "")); }
  }
  return partes.join(" e ");
}
function valorPorExtenso(valor) {
  valor = Math.round(Math.abs(Number(valor || 0)) * 100) / 100;
  const inteiro = Math.floor(valor);
  const centavos = Math.round((valor - inteiro) * 100);
  if (inteiro === 0 && centavos === 0) return "zero reais";
  const milhoes = Math.floor(inteiro / 1000000);
  const milhares = Math.floor((inteiro % 1000000) / 1000);
  const unidade = inteiro % 1000;
  const partes = [];
  if (milhoes) partes.push(extensoGrupo(milhoes) + (milhoes === 1 ? " milhão" : " milhões"));
  if (milhares) partes.push(milhares === 1 ? "mil" : extensoGrupo(milhares) + " mil");
  if (unidade) partes.push(extensoGrupo(unidade));
  let resultado = inteiro > 0 ? `${partes.join(", ")} ${inteiro === 1 ? "real" : "reais"}` : "";
  if (centavos > 0) {
    const centavosTxt = `${extensoGrupo(centavos)} ${centavos === 1 ? "centavo" : "centavos"}`;
    resultado = resultado ? `${resultado} e ${centavosTxt}` : centavosTxt;
  }
  return resultado;
}
