function textoClausula(comprador, chave, n, vendedorNome) {
  const def = CLAUSULAS_CONTRATO[chave];
  const padrao = (def.defaultMilho && n.grao === "Milho") ? def.defaultMilho
    : (def.defaultSorgo && n.grao === "Sorgo") ? def.defaultSorgo
    : def.default;
  const bruto = (comprador[def.campo] || "").trim() || padrao;
  return escapeHtml(bruto)
    .replace(/\{\{VENDEDOR\}\}/g, vendedorNome || "")
    .replace(/\{\{COMPRADOR\}\}/g, comprador.nome)
    .replace(/\{\{COMISSAO_SACA\}\}/g, fmtMoney(n.comissao_saca || 0))
    .replace(/\{\{COMISSAO_PAGADOR\}\}/g, (n.comissao_pagador || "Vendedor").toUpperCase());
}
